package com.trampolim.api.career;
import java.util.*;import static com.trampolim.api.radar.RadarModel.*;import com.trampolim.api.radar.*;import org.springframework.web.bind.annotation.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.beans.factory.annotation.Qualifier;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/career")
public class CareerCoachingController {
 private final JdbcTemplate jdbc;private final SkillCatalog users;private final RadarBridge bridge;private final CareerAiService ai;
 public CareerCoachingController(@Qualifier("jdbcTemplate")JdbcTemplate jdbc,SkillCatalog users,RadarBridge bridge,CareerAiService ai){this.jdbc=jdbc;this.users=users;this.bridge=bridge;this.ai=ai;}
 public record Start(String area,String occupation,Long listingId){}public record Answer(int question,String text,int revision,UUID clientKey,boolean useAi,boolean consent){}public record Step(String notes){}
 @GetMapping("/mentor/status")public Map<String,Object> status(@AuthenticationPrincipal String email){return ai.status(email);}
 @PostMapping("/mentor")public Map<String,Object> mentor(@AuthenticationPrincipal String email,@RequestBody CareerAiService.Ask input){return ai.ask(email,input);}
 @GetMapping("/interviews")public List<Map<String,Object>> interviews(@AuthenticationPrincipal String email){return jdbc.queryForList("SELECT id,area,occupation,revision,completed_at,created_at FROM career_interview_sessions WHERE user_id=? ORDER BY created_at DESC LIMIT 50",users.user(email));}
 private Map<String,Object> own(long uid,UUID id){var row=jdbc.queryForList("SELECT id,area,occupation,questions,answers,feedback,revision,completed_at,created_at FROM career_interview_sessions WHERE id=? AND user_id=?",id,uid).stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));for(String key:List.of("questions","answers","feedback"))row.put(key,bridge.convert(bridge.read(row.get(key)),Object.class));return row;}
 @GetMapping("/interviews/{id}")public Map<String,Object> interview(@AuthenticationPrincipal String email,@PathVariable UUID id){return own(users.user(email),id);}
 @PostMapping("/interviews")@Transactional("oportunidadesTransactionManager")public Map<String,Object> start(@AuthenticationPrincipal String email,@RequestBody Start input){long uid=users.user(email);if(input==null||text(input.area(),80).isEmpty()||text(input.occupation(),180).isEmpty())bad("Informe área e ocupação.");if(input.listingId()!=null)bridge.get("/public/companies/radar-jobs/"+input.listingId());jdbc.queryForObject("SELECT id FROM app_users WHERE id=? FOR UPDATE",Long.class,uid);if(jdbc.queryForObject("SELECT count(*) FROM career_interview_sessions WHERE user_id=? AND created_at>CURRENT_TIMESTAMP-INTERVAL '1 day'",Integer.class,uid)>=10)throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,"Limite diário de dez simulações atingido.");UUID id=UUID.randomUUID();var questions=List.of("O que você aprendeu em estudos, projetos ou experiências reais que se relaciona com esta ocupação?","Descreva uma situação concreta, sua ação e o resultado observado ao resolver um problema.","Como você organizaria os próximos passos para desenvolver uma competência exigida nesta área?");jdbc.update("INSERT INTO career_interview_sessions(id,user_id,area,occupation,listing_id,questions) VALUES (?,?,?,?,?,?::jsonb)",id,uid,input.area().trim(),input.occupation().trim(),input.listingId(),bridge.encode(questions));return own(uid,id);}
 @PostMapping("/interviews/{id}/answers")public Map<String,Object> answer(@AuthenticationPrincipal String email,@PathVariable UUID id,@RequestBody Answer input){long uid=users.user(email);var session=own(uid,id);if(input==null||input.question()<0||input.question()>2||text(input.text(),2500).isEmpty()||input.clientKey()==null)bad("Responda uma pergunta com até 2.500 caracteres.");if(((Number)session.get("revision")).intValue()!=input.revision())throw new ResponseStatusException(HttpStatus.CONFLICT,"A simulação mudou; reabra antes de responder.");var questions=(List<String>)session.get("questions");var feedback=ai.ask(email,new CareerAiService.Ask(input.clientKey(),"INTERVIEW","Área: "+session.get("area")+"; ocupação: "+session.get("occupation")+"; pergunta: "+questions.get(input.question())+"; resposta: "+input.text(),input.useAi(),input.consent()));var answers=new TreeMap<String,Object>((Map<String,Object>)session.get("answers"));answers.put(Integer.toString(input.question()),CareerRules.redact(input.text()));var feedbacks=new TreeMap<String,Object>((Map<String,Object>)session.get("feedback"));feedbacks.put(Integer.toString(input.question()),feedback);if(jdbc.update("UPDATE career_interview_sessions SET answers=?::jsonb,feedback=?::jsonb,revision=revision+1,completed_at=CASE WHEN ?=3 THEN CURRENT_TIMESTAMP ELSE NULL END WHERE id=? AND user_id=? AND revision=?",bridge.encode(answers),bridge.encode(feedbacks),answers.size(),id,uid,input.revision())==0)throw new ResponseStatusException(HttpStatus.CONFLICT,"A simulação foi alterada em outra sessão.");return own(uid,id);}
 @GetMapping("/first-job")public Map<String,Object> first(@AuthenticationPrincipal String email){long uid=users.user(email);var result=new LinkedHashMap<String,Object>();result.put("observed",jdbc.queryForMap("SELECT EXISTS(SELECT 1 FROM app_users WHERE id=? AND (resume_file_name IS NOT NULL OR length(COALESCE(summary,''))>20)) AS resume_prepared,EXISTS(SELECT 1 FROM career_interview_sessions WHERE user_id=? AND completed_at IS NOT NULL) AS interview_practiced,EXISTS(SELECT 1 FROM career_challenge_submissions WHERE user_id=? AND withdrawn_at IS NULL) AS project_submitted",uid,uid,uid));result.put("declaredPlans",jdbc.queryForList("SELECT step,notes,updated_at FROM career_first_job_steps WHERE user_id=?",uid));try{result.put("training",bridge.convert(bridge.get("/public/capacita/radar/training?codes=digital-literacy,communication,teamwork,time-management"),List.class));}catch(ResponseStatusException unavailable){result.put("training",List.of());result.put("trainingStatus","UNAVAILABLE");}result.put("notice","Jornada de preparação, sem garantia de emprego. Planos são declarações pessoais; marcos observados dependem dos registros reais da plataforma. Cursos concluídos devem ser comprovados no Capacita/Passaporte.");return result;}
 @PutMapping("/first-job/{step}")@ResponseStatus(HttpStatus.NO_CONTENT)public void step(@AuthenticationPrincipal String email,@PathVariable String step,@RequestBody Step input){if(!Set.of("RESUME_PLAN","TRAINING_PLAN","APPLICATION_PLAN").contains(step)||input==null)bad("Etapa inválida.");jdbc.update("INSERT INTO career_first_job_steps(user_id,step,notes) VALUES (?,?,?) ON CONFLICT(user_id,step) DO UPDATE SET notes=EXCLUDED.notes,updated_at=CURRENT_TIMESTAMP",users.user(email),step,text(input.notes(),1000));}
}
